css:
:root{
  --mask-l:50% 0 0 50%/50% 0 0 50%;
  --mask-r:0 50% 50% 0/0 50% 50% 0;
  --hex:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);
  --caps:58px/46px;                       /* 縦長カプセル 115x175px 用 */
}
.row:nth-child(odd)  figure{border-radius:var(--mask-l);margin-right:calc(50% - 50vw)}
.row:nth-child(even) figure{border-radius:var(--mask-r);margin-left:calc(50% - 50vw)}
.card,.thumb,.avatar{clip-path:var(--hex)}
.oval{clip-path:ellipse(50% 50% at 50% 50%);aspect-ratio:1.35/1}
.pill{border-radius:var(--caps);overflow:hidden;box-shadow:0 0 0 6px #fff}
